import narwhals as nw
import pandas as pd
import polars as pl

@nw.narwhalify
def add_total(df):
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )

# Example with pandas
pandas_df = pd.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
result_pandas = add_total(pandas_df)
print("Pandas result:")
print(result_pandas)
print()

# Example with polars
polars_df = pl.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
result_polars = add_total(polars_df)
print("Polars result:")
print(result_polars)
